Assuming the string is named 'someString' you can output the string to the 

#include <iostream>
using namespace std;

int main() {
  std::cout << someString << "\n";
  return 0;
}
alternatively you may use the native printf function

int main() {
  printf("%s\n",someString.c_str());
  return 0;
}

